#include "args.h"
#include <iostream>
#include <algorithm>
#include <stdexcept>

Args::Args() {
  lr = 0.05;
  dim = 100;
  ws = 5;
  epoch = 5;
  minCount = 5;
  minCountLabel = 0;
  neg = 5;
  wordNgrams = 1;
  loss = loss_name::ns;
  model = model_name::cbow;
  bucket = 2000000;
  minn = 3;
  maxn = 6;
  lrUpdateRate = 100;
  t = 0.0001;
  label = "__label__";
  verbose = 2;
  thread = 12;
  pretrainedVectors = "";
  saveOutput = false;
  seed = 0;
  autotune = false;
  autotunePredictions = 1;
  autotuneDuration = 300;
  cutoff = 0;
  retrain = false;
  qnorm = false;
  qout = false;
  dsub = 2;
}

void Args::parseArgs(const std::vector<std::string>& args) {
  std::string command = args[1];
  if (command == "supervised") {
    model = model_name::sup;
    loss = loss_name::softmax;
    minCount = 1;
    minn = 0;
    maxn = 0;
    lr = 0.1;
  } else if (command == "skipgram") {
    model = model_name::skipgram;
  } else if (command == "cbow") {
    model = model_name::cbow;
  }
  for (int i = 2; i < args.size(); i++) {
    if (args[i][0] != '-') continue;
    try {
      if (args[i] == "-h") {
        printHelp();
        exit(0);
      } else if (args[i] == "-input") {
        input = args.at(i + 1); i++;
      } else if (args[i] == "-output") {
        output = args.at(i + 1); i++;
      } else if (args[i] == "-lr") {
        lr = std::stod(args.at(i + 1)); i++;
      } else if (args[i] == "-lrUpdateRate") {
        lrUpdateRate = std::stoi(args.at(i + 1)); i++;
      } else if (args[i] == "-dim") {
        dim = std::stoi(args.at(i + 1)); i++;
      } else if (args[i] == "-ws") {
        ws = std::stoi(args.at(i + 1)); i++;
      } else if (args[i] == "-epoch") {
        epoch = std::stoi(args.at(i + 1)); i++;
      } else if (args[i] == "-minCount") {
        minCount = std::stoi(args.at(i + 1)); i++;
      } else if (args[i] == "-minCountLabel") {
        minCountLabel = std::stoi(args.at(i + 1)); i++;
      } else if (args[i] == "-neg") {
        neg = std::stoi(args.at(i + 1)); i++;
      } else if (args[i] == "-wordNgrams") {
        wordNgrams = std::stoi(args.at(i + 1)); i++;
      } else if (args[i] == "-loss") {
        std::string l = args.at(i + 1); i++;
        if (l == "hs") loss = loss_name::hs;
        else if (l == "ns") loss = loss_name::ns;
        else if (l == "softmax") loss = loss_name::softmax;
        else if (l == "one-vs-all") loss = loss_name::ova;
        else throw std::invalid_argument("Unknown loss: " + l);
      } else if (args[i] == "-bucket") {
        bucket = std::stoi(args.at(i + 1)); i++;
      } else if (args[i] == "-minn") {
        minn = std::stoi(args.at(i + 1)); i++;
      } else if (args[i] == "-maxn") {
        maxn = std::stoi(args.at(i + 1)); i++;
      } else if (args[i] == "-thread") {
        thread = std::stoi(args.at(i + 1)); i++;
      } else if (args[i] == "-t") {
        t = std::stod(args.at(i + 1)); i++;
      } else if (args[i] == "-label") {
        label = args.at(i + 1); i++;
      } else if (args[i] == "-verbose") {
        verbose = std::stoi(args.at(i + 1)); i++;
      } else if (args[i] == "-pretrainedVectors") {
        pretrainedVectors = args.at(i + 1); i++;
      } else if (args[i] == "-saveOutput") {
        saveOutput = args.at(i + 1) == "true"; i++;
      } else if (args[i] == "-seed") {
        seed = std::stoi(args.at(i + 1)); i++;
      } else if (args[i] == "-cutoff") {
        cutoff = std::stoi(args.at(i + 1)); i++;
      } else if (args[i] == "-dsub") {
        dsub = std::stoi(args.at(i + 1)); i++;
      } else if (args[i] == "-retrain") {
        retrain = args.at(i + 1) == "true"; i++;
      } else if (args[i] == "-qnorm") {
        qnorm = args.at(i + 1) == "true"; i++;
      } else if (args[i] == "-qout") {
        qout = args.at(i + 1) == "true"; i++;
      } else {
        throw std::invalid_argument("Unknown argument: " + args[i]);
      }
    } catch (std::out_of_range& e) {
      throw std::invalid_argument(args[i] + " requires an argument");
    }
  }
  if (input.empty() || output.empty()) {
    throw std::invalid_argument("Empty input or output path.");
  }
}

void Args::printHelp() {
  // This is a simplified version of the help
  std::cout << "usage: fasttext <command> <args>" << std::endl;
}
