#include <string>
#include <unordered_map>
#include <iostream>
#include "args.h"

enum class entry_type : int8_t { word = 1, label = 2 };

struct entry {
  std::string word;
  int64_t count;
  entry_type type;
  std::vector<int32_t> subwords;
};

class Dictionary {
public:
  Dictionary(std::shared_ptr<Args> args);
  void train(std::istream& in);
  int32_t getId(const std::string& word) const;
  entry_type getType(int32_t id) const;
  const std::string& getWord(int32_t id) const;
  int32_t nwords() const;
  int32_t nlabels() const;
  int64_t ntokens() const;
  void save(std::ostream& out) const;
  void load(std::istream& in);
  void getSubwords(int32_t id, std::vector<int32_t>& subwords) const;
  void getSubwords(const std::string& word, std::vector<int32_t>& subwords) const;
  void computeSubwords(const std::string& word, std::vector<int32_t>& subwords) const;
  int32_t getLine(std::istream& in, std::vector<int32_t>& words, std::vector<int32_t>& labels) const;

private:
  static const int32_t MAX_VOCAB_SIZE = 30000000;
  static const std::string EOS;
  std::shared_ptr<Args> args_;
  std::vector<int32_t> word2hash_;
  std::vector<entry> words_;
  std::unordered_map<std::string, int32_t> word2id_;
  int32_t nwords_;
  int32_t nlabels_;
  int64_t ntokens_;

  int32_t find(const std::string& word) const;
  void add(const std::string& word);
  void initTableValues();
};

#endif
