#include "dictionary.h"
#include <algorithm>
#include <iostream>
#include <fstream>

const std::string Dictionary::EOS = "</s>";

Dictionary::Dictionary(std::shared_ptr<Args> args) : args_(args), nwords_(0), nlabels_(0), ntokens_(0) {}

int32_t Dictionary::find(const std::string& word) const {
  auto it = word2id_.find(word);
  if (it == word2id_.end()) return -1;
  return it->second;
}

void Dictionary::add(const std::string& word) {
  int32_t id = find(word);
  ntokens_++;
  if (id == -1) {
    entry e;
    e.word = word;
    e.count = 1;
    e.type = (word.find(args_->label) == 0) ? entry_type::label : entry_type::word;
    words_.push_back(e);
    word2id_[word] = words_.size() - 1;
  } else {
    words_[id].count++;
  }
}

void Dictionary::train(std::istream& in) {
  std::string word;
  while (in >> word) {
    add(word);
  }
  add(EOS);

  // Filter and Sort
  std::vector<entry> new_words;
  for (auto& e : words_) {
    if ((e.type == entry_type::word && e.count >= args_->minCount) ||
        (e.type == entry_type::label && e.count >= args_->minCountLabel)) {
      new_words.push_back(e);
    }
  }

  // Sort: words first, then labels. Within each group, by count descending.
  // Actually, fastText sorts all of them by count descending, but labels stay in the same list.
  // Wait, let's check the original order again.
  std::sort(new_words.begin(), new_words.end(), [](const entry& a, const entry& b) {
    if (a.type != b.type) return a.type < b.type;
    return a.count > b.count;
  });

  words_ = new_words;
  word2id_.clear();
  nwords_ = 0;
  nlabels_ = 0;
  for (int32_t i = 0; i < words_.size(); i++) {
    word2id_[words_[i].word] = i;
    if (words_[i].type == entry_type::word) nwords_++;
    else nlabels_++;
  }
}

int32_t Dictionary::getId(const std::string& word) const {
  return find(word);
}

entry_type Dictionary::getType(int32_t id) const {
  return words_[id].type;
}

const std::string& Dictionary::getWord(int32_t id) const {
  return words_[id].word;
}

int32_t Dictionary::nwords() const { return nwords_; }
int32_t Dictionary::nlabels() const { return nlabels_; }
int64_t Dictionary::ntokens() const { return ntokens_; }

void Dictionary::save(std::ostream& out) const {
  int32_t size = words_.size();
  out.write((char*)&size, sizeof(int32_t));
  out.write((char*)&nwords_, sizeof(int32_t));
  out.write((char*)&nlabels_, sizeof(int32_t));
  out.write((char*)&ntokens_, sizeof(int64_t));
  int64_t pruneidx = -1;
  out.write((char*)&pruneidx, sizeof(int64_t));
  for (const auto& e : words_) {
    out.write(e.word.data(), e.word.size());
    out.put(0);
    out.write((char*)&e.count, sizeof(int64_t));
    out.write((char*)&e.type, sizeof(int8_t));
  }
}

void Dictionary::load(std::istream& in) {
  int32_t size;
  in.read((char*)&size, sizeof(int32_t));
  in.read((char*)&nwords_, sizeof(int32_t));
  in.read((char*)&nlabels_, sizeof(int32_t));
  in.read((char*)&ntokens_, sizeof(int64_t));
  int64_t pruneidx;
  in.read((char*)&pruneidx, sizeof(int64_t));
  words_.clear();
  word2id_.clear();
  for (int32_t i = 0; i < size; i++) {
    entry e;
    char c;
    while (in.get(c) && c != 0) e.word += c;
    in.read((char*)&e.count, sizeof(int64_t));
    in.read((char*)&e.type, sizeof(int8_t));
    words_.push_back(e);
    word2id_[e.word] = i;
  }
}

uint32_t hash_func(const std::string& str) {
  uint32_t h = 2166136261;
  for (size_t i = 0; i < str.size(); i++) {
    h = h ^ (uint32_t)(static_cast<signed char>(str[i]));
    h = h * 16777619;
  }
  return h;
}

void Dictionary::computeSubwords(const std::string& word, std::vector<int32_t>& subwords) const {
  if (word == EOS) return;
  std::string extended_word = "<" + word + ">";
  for (size_t i = 0; i < extended_word.size(); i++) {
    std::string ngram;
    for (size_t j = i, n = 1; j < extended_word.size() && n <= args_->maxn; n++) {
      ngram += extended_word[j++];
      if (n >= args_->minn) {
        int32_t h = hash_func(ngram) % args_->bucket;
        subwords.push_back(nwords_ + h);
      }
    }
  }
}

void Dictionary::getSubwords(int32_t id, std::vector<int32_t>& subwords) const {
  subwords.push_back(id);
  if (id < nwords_) {
    computeSubwords(words_[id].word, subwords);
  }
}

void Dictionary::getSubwords(const std::string& word, std::vector<int32_t>& subwords) const {
  int32_t id = find(word);
  if (id != -1) {
    getSubwords(id, subwords);
  } else {
    computeSubwords(word, subwords);
  }
}

int32_t Dictionary::getLine(std::istream& in, std::vector<int32_t>& words, std::vector<int32_t>& labels) const {
  std::vector<int32_t> line_words;
  std::vector<int32_t> line_labels;
  std::string word;
  int32_t count = 0;
  std::string line;
  if (!std::getline(in, line)) return -1;
  std::stringstream ss(line);
  while (ss >> word) {
    int32_t id = find(word);
    if (id == -1) continue;
    if (getType(id) == entry_type::word) {
      words.push_back(id);
    } else {
      labels.push_back(id - nwords_);
    }
    count++;
  }
  words.push_back(find(EOS));
  return count;
}
