void Dictionary::computeSubwords(const std::string& word, std::vector<int32_t>& subwords) const {
  if (word == EOS) return;
  std::string extended_word = "<" + word + ">";
  for (size_t i = 0; i < extended_word.size(); i++) {
    std::string ngram;
    for (size_t j = i, n = 1; j < extended_word.size() && n <= args_->maxn; n++) {
      ngram += extended_word[j++];
      if (n >= args_->minn) {
        int32_t h = hash_func(ngram) % args_->bucket;
        subwords.push_back(nwords_ + h);
      }
    }
  }
}

void Dictionary::getSubwords(int32_t id, std::vector<int32_t>& subwords) const {
  subwords.push_back(id);
  if (id < nwords_) {
    computeSubwords(words_[id].word, subwords);
  }
}

void Dictionary::getSubwords(const std::string& word, std::vector<int32_t>& subwords) const {
  int32_t id = find(word);
  if (id != -1) {
    getSubwords(id, subwords);
  } else {
    computeSubwords(word, subwords);
  }
}

