  std::vector<int32_t> line_words;
  std::vector<int32_t> line_labels;
  std::string word;
  int32_t count = 0;
  std::string line;
  if (!std::getline(in, line)) return -1;
  std::stringstream ss(line);
  while (ss >> word) {
    int32_t id = find(word);
    if (id == -1) continue;
    if (getType(id) == entry_type::word) {
      words.push_back(id);
    } else {
      labels.push_back(id - nwords_);
    }
    count++;
  }
  words.push_back(find(EOS));
  return count;
}
