#include "model.h"
#include <cmath>
#include <algorithm>

Model::Model(std::shared_ptr<Matrix> wi, std::shared_ptr<Matrix> wo, std::shared_ptr<Args> args, int32_t seed)
    : wi_(wi), wo_(wo), args_(args), rng_(seed), hidden_(args->dim), grad_(args->dim), neg_pos_(0) {
  initSigmoid();
}

void Model::initSigmoid() {
  t_sigmoid_.resize(513);
  for (int i = 0; i < 513; i++) {
    float x = (float(i) - 256.0) / 256.0 * 8.0;
    t_sigmoid_[i] = 1.0 / (1.0 + std::exp(-x));
  }
}

float Model::sigmoid(float x) {
  if (x < -8.0) return 0.0;
  if (x > 8.0) return 1.0;
  int i = int((x + 8.0) * 512.0 / 16.0);
  return t_sigmoid_[i];
}

void Model::computeHidden(const std::vector<int32_t>& input, std::vector<float>& hidden) {
  std::fill(hidden.begin(), hidden.end(), 0.0);
  for (auto i : input) {
    for (int d = 0; d < args_->dim; d++) {
      hidden[d] += wi_->at(i, d);
    }
  }
  if (!input.empty()) {
    for (int d = 0; d < args_->dim; d++) {
      hidden[d] /= input.size();
    }
  }
}

float Model::softmax(int32_t target, float lr) {
  std::vector<float> output(wo_->size(0));
  float max_out = -1e30, sum_exp = 0.0;
  for (int i = 0; i < wo_->size(0); i++) {
    output[i] = 0.0;
    for (int d = 0; d < args_->dim; d++) {
      output[i] += hidden_[d] * wo_->at(i, d);
    }
    if (output[i] > max_out) max_out = output[i];
  }
  for (int i = 0; i < wo_->size(0); i++) {
    output[i] = std::exp(output[i] - max_out);
    sum_exp += output[i];
  }

  std::fill(grad_.begin(), grad_.end(), 0.0);
  for (int i = 0; i < wo_->size(0); i++) {
    float prob = output[i] / sum_exp;
    float alpha = lr * ((i == target ? 1.0 : 0.0) - prob);
    for (int d = 0; d < args_->dim; d++) {
      grad_[d] += alpha * wo_->at(i, d);
      wo_->at(i, d) += alpha * hidden_[d];
    }
  }
  return -std::log(output[target] / sum_exp);
}

float Model::negativeSampling(int32_t target, float lr) {
  float loss = 0.0;
  std::fill(grad_.begin(), grad_.end(), 0.0);
  for (int n = 0; n <= args_->neg; n++) {
    int32_t sample, label;
    if (n == 0) {
      sample = target;
      label = 1;
    } else {
      sample = negatives_[neg_pos_];
      neg_pos_ = (neg_pos_ + 1) % negatives_.size();
      if (sample == target) continue;
      label = 0;
    }
    float f = 0.0;
    for (int d = 0; d < args_->dim; d++) f += hidden_[d] * wo_->at(sample, d);
    float sigm = sigmoid(f);
    float alpha = lr * (label - sigm);
    for (int d = 0; d < args_->dim; d++) {
      grad_[d] += alpha * wo_->at(sample, d);
      wo_->at(sample, d) += alpha * hidden_[d];
    }
    loss -= (label == 1) ? std::log(sigm) : std::log(1.0 - sigm);
  }
  return loss;
}

