  if (input.empty()) return;
  computeHidden(input, hidden_);
  if (args_->loss == loss_name::softmax) {
    for (auto t : targets) softmax(t, lr);
  } else if (args_->loss == loss_name::ns) {
    for (auto t : targets) negativeSampling(t, lr);
