    for (int d = 0; d < args_->dim; d++) score += hidden_[d] * wo_->at(i, d);
    results.push_back({score, i});
  }
  std::sort(results.rbegin(), results.rend());

  float sum_exp = 0.0;
  if (args_->loss == loss_name::softmax) {
    float max_score = results[0].first;
    for (auto& p : results) {
      p.first = std::exp(p.first - max_score);
      sum_exp += p.first;
    }
    for (auto& p : results) p.first /= sum_exp;
  } else {
