#include "fasttext.h"
#include <fstream>
#include <iomanip>
#include <cmath>
#include <algorithm>
#include <random>
#include <sstream>

void FastText::train(std::shared_ptr<Args> args) {
  args_ = args;
  dict_ = std::make_shared<Dictionary>(args_);
  std::ifstream ifs(args_->input);
  if (!ifs.is_open()) throw std::runtime_error("Cannot open input file");
  dict_->train(ifs);
  ifs.close();

  input_ = std::make_shared<Matrix>(dict_->nwords() + args_->bucket, args_->dim);
  input_->uniform(1.0 / args_->dim);
  if (args_->model == model_name::sup) {
    output_ = std::make_shared<Matrix>(dict_->nlabels(), args_->dim);
  } else {
    output_ = std::make_shared<Matrix>(dict_->nwords(), args_->dim);
  }
  output_->zero();

  for (int epoch = 0; epoch < args_->epoch; epoch++) {
    std::ifstream ifs_train(args_->input);
    std::shared_ptr<Model> model = std::make_shared<Model>(input_, output_, args_, args_->seed);
    if (args_->loss == loss_name::ns) {
      std::vector<int64_t> counts;
      for (int i = 0; i < dict_->nwords(); i++) counts.push_back(1);
      model->initNegatives(counts);
    }
    std::vector<int32_t> line, labels;
    while (dict_->getLine(ifs_train, line, labels) != -1) {
      float progress = (float)epoch / args_->epoch;
      float lr = args_->lr * (1.0 - progress);
      if (args_->model == model_name::sup) {
        std::vector<int32_t> subwords;
        for (auto w : line) dict_->getSubwords(w, subwords);
        model->update(subwords, labels, lr);
      } else {
        // skipgram or cbow
        for (int i = 0; i < line.size(); i++) {
          std::minstd_rand rng(args_->seed + i);
          std::uniform_int_distribution<int> dist(1, args_->ws);
          int boundary = dist(rng);
          std::vector<int32_t> subwords;
          dict_->getSubwords(line[i], subwords);
          if (args_->model == model_name::skipgram) {
            for (int j = i - boundary; j <= i + boundary; j++) {
              if (i == j || j < 0 || j >= line.size()) continue;
              if (line[j] != -1) model->update(subwords, {line[j]}, lr);
            }
          } else {
            // CBOW
            std::vector<int32_t> context;
            for (int j = i - boundary; j <= i + boundary; j++) {
              if (i == j || j < 0 || j >= line.size()) continue;
              if (line[j] != -1) {
                std::vector<int32_t> sw;
                dict_->getSubwords(line[j], sw);
                context.insert(context.end(), sw.begin(), sw.end());
              }
            }
            if (!context.empty()) model->update(context, {line[i]}, lr);
          }
        }
      }
      line.clear();
      labels.clear();
    }
  }
  saveModel(args_->output + ".bin");
  if (args_->saveOutput) saveVectors(args_->output + ".vec");
}

void FastText::saveModel(const std::string& filename) {
  std::ofstream ofs(filename, std::ios::binary);
  int32_t magic = 0x2f4f16ba, version = 12;
  ofs.write((char*)&magic, sizeof(int32_t));
  ofs.write((char*)&version, sizeof(int32_t));
  ofs.write((char*)&args_->dim, sizeof(int32_t));
  ofs.write((char*)&args_->ws, sizeof(int32_t));
  ofs.write((char*)&args_->epoch, sizeof(int32_t));
  ofs.write((char*)&args_->minCount, sizeof(int32_t));
  ofs.write((char*)&args_->neg, sizeof(int32_t));
  ofs.write((char*)&args_->wordNgrams, sizeof(int32_t));
  int32_t loss = (int32_t)args_->loss, model = (int32_t)args_->model;
  ofs.write((char*)&loss, sizeof(int32_t));
  ofs.write((char*)&model, sizeof(int32_t));
  ofs.write((char*)&args_->bucket, sizeof(int32_t));
  ofs.write((char*)&args_->minn, sizeof(int32_t));
  ofs.write((char*)&args_->maxn, sizeof(int32_t));
  ofs.write((char*)&args_->lrUpdateRate, sizeof(int32_t));
  ofs.write((char*)&args_->t, sizeof(double));
  dict_->save(ofs);
  input_->save(ofs);
  output_->save(ofs);
}

void FastText::loadModel(const std::string& filename) {
  std::ifstream ifs(filename, std::ios::binary);
  if (!ifs.is_open()) throw std::runtime_error("Cannot open model file");
  int32_t magic, version;
  ifs.read((char*)&magic, sizeof(int32_t));
  ifs.read((char*)&version, sizeof(int32_t));
  args_ = std::make_shared<Args>();
  ifs.read((char*)&args_->dim, sizeof(int32_t));
  ifs.read((char*)&args_->ws, sizeof(int32_t));
  ifs.read((char*)&args_->epoch, sizeof(int32_t));
  ifs.read((char*)&args_->minCount, sizeof(int32_t));
  ifs.read((char*)&args_->neg, sizeof(int32_t));
  ifs.read((char*)&args_->wordNgrams, sizeof(int32_t));
  int32_t loss, model;
  ifs.read((char*)&loss, sizeof(int32_t));
  args_->loss = (loss_name)loss;
  ifs.read((char*)&model, sizeof(int32_t));
  args_->model = (model_name)model;
  ifs.read((char*)&args_->bucket, sizeof(int32_t));
  ifs.read((char*)&args_->minn, sizeof(int32_t));
  ifs.read((char*)&args_->maxn, sizeof(int32_t));
  ifs.read((char*)&args_->lrUpdateRate, sizeof(int32_t));
  ifs.read((char*)&args_->t, sizeof(double));
  dict_ = std::make_shared<Dictionary>(args_);
  dict_->load(ifs);
  input_ = std::make_shared<Matrix>();
  input_->load(ifs);
  output_ = std::make_shared<Matrix>();
  output_->load(ifs);
}

void FastText::saveVectors(const std::string& filename) {
  std::ofstream ofs(filename);
  ofs << dict_->nwords() << " " << args_->dim << std::endl;
  for (int i = 0; i < dict_->nwords(); i++) {
    ofs << dict_->getWord(i);
    std::vector<int32_t> subwords;
    dict_->getSubwords(i, subwords);
    std::vector<float> vec(args_->dim, 0.0);
    for (auto s : subwords) for (int d = 0; d < args_->dim; d++) vec[d] += input_->at(s, d);
    for (int d = 0; d < args_->dim; d++) ofs << " " << std::fixed << std::setprecision(5) << vec[d] / subwords.size();
    ofs << std::endl;
  }
}

void FastText::predict(std::istream& in, int32_t k, float threshold, bool print_prob) {
  std::string line;
  std::shared_ptr<Model> model = std::make_shared<Model>(input_, output_, args_, 0);
  while (std::getline(in, line)) {
    std::stringstream ss(line);
    std::string word;
    std::vector<int32_t> subwords;
    while (ss >> word) {
      int32_t id = dict_->getId(word);
      std::vector<int32_t> sw;
      if (id != -1) dict_->getSubwords(id, sw);
      else dict_->computeSubwords(word, sw);
      subwords.insert(subwords.end(), sw.begin(), sw.end());
    }
    std::vector<std::pair<float, int32_t>> predictions;
    model->predict(subwords, k, threshold, predictions);
    for (int i = 0; i < predictions.size(); i++) {
      std::cout << dict_->getWord(predictions[i].second + dict_->nwords());
      if (print_prob) std::cout << " " << predictions[i].first;
      if (i < predictions.size() - 1) std::cout << " ";
    }
    std::cout << std::endl;
  }
}

void FastText::test(std::istream& in, int32_t k, float threshold) {
  int32_t n = 0, n_correct = 0;
  std::string line;
  std::shared_ptr<Model> model = std::make_shared<Model>(input_, output_, args_, 0);
  while (std::getline(in, line)) {
    std::stringstream ss(line);
    std::string word;
    std::vector<int32_t> subwords, labels;
    while (ss >> word) {
      if (word.find(args_->label) == 0) {
        int32_t id = dict_->getId(word);
        if (id != -1) labels.push_back(id - dict_->nwords());
      } else {
        int32_t id = dict_->getId(word);
        std::vector<int32_t> sw;
        if (id != -1) dict_->getSubwords(id, sw);
        else dict_->computeSubwords(word, sw);
        subwords.insert(subwords.end(), sw.begin(), sw.end());
      }
    }
    std::vector<std::pair<float, int32_t>> predictions;
    model->predict(subwords, k, threshold, predictions);
    n++;
    for (auto p : predictions) {
      for (auto l : labels) {
        if (p.second == l) { n_correct++; break; }
      }
    }
  }
  std::cout << "N\t" << n << std::endl;
  std::cout << "P@" << k << "\t" << std::fixed << std::setprecision(3) << (float)n_correct / (n * k) << std::endl;
  std::cout << "R@" << k << "\t" << std::fixed << std::setprecision(3) << (float)n_correct / n << std::endl;
}

void FastText::printWordVectors(std::istream& in) {
  std::string word;
  while (in >> word) {
    std::vector<int32_t> subwords;
    dict_->getSubwords(word, subwords);
    std::vector<float> vec(args_->dim, 0.0);
    for (auto s : subwords) for (int d = 0; d < args_->dim; d++) vec[d] += input_->at(s, d);
    std::cout << word;
    for (int d = 0; d < args_->dim; d++) std::cout << " " << std::fixed << std::setprecision(5) << vec[d] / subwords.size();
    std::cout << std::endl;
  }
}

void FastText::nn(int32_t k) {
  std::string query_word;
  while (std::cout << "Query word? ", std::cin >> query_word) {
    std::vector<int32_t> subwords;
    dict_->getSubwords(query_word, subwords);
    std::vector<float> query_vec(args_->dim, 0.0);
    for (auto s : subwords) for (int d = 0; d < args_->dim; d++) query_vec[d] += input_->at(s, d);
    float q_norm = 0.0;
    for (auto x : query_vec) q_norm += x * x;
    q_norm = std::sqrt(q_norm);
    if (q_norm > 0) for (auto& x : query_vec) x /= q_norm;

    std::vector<std::pair<float, std::string>> results;
    for (int i = 0; i < dict_->nwords(); i++) {
      std::string w = dict_->getWord(i);
      std::vector<int32_t> sw;
      dict_->getSubwords(i, sw);
      std::vector<float> v(args_->dim, 0.0);
      for (auto s : sw) for (int d = 0; d < args_->dim; d++) v[d] += input_->at(s, d);
      float v_norm = 0.0;
      for (auto x : v) v_norm += x * x;
      v_norm = std::sqrt(v_norm);
      float dot = 0.0;
      if (v_norm > 0) for (int d = 0; d < args_->dim; d++) dot += query_vec[d] * (v[d] / v_norm);
      results.push_back({dot, w});
    }
    std::sort(results.rbegin(), results.rend());
    for (int i = 0; i < k && i < results.size(); i++) std::cout << results[i].second << " " << results[i].first << std::endl;
  }
}

void FastText::analogies(int32_t k) {
  std::string w1, w2, w3;
  while (std::cout << "Query triplet (A B C)? ", std::cin >> w1 >> w2 >> w3) {
    // A - B + C ? no, fasttext uses A - B + C. Wait, it is usually A:B :: C:D => D = B - A + C
    // ...
  }
}

void FastText::dump(const std::string& filename, const std::string& option) {
  loadModel(filename);
  if (option == "args") {
    std::cout << "dim " << args_->dim << "\nws " << args_->ws << "\nepoch " << args_->epoch << "\nminCount " << args_->minCount 
              << "\nneg " << args_->neg << "\nwordNgrams " << args_->wordNgrams << "\nloss " << (int)args_->loss 
              << "\nmodel " << (int)args_->model << "\nbucket " << args_->bucket << "\nminn " << args_->minn 
              << "\nmaxn " << args_->maxn << "\nlrUpdateRate " << args_->lrUpdateRate << "\nt " << args_->t << std::endl;
  } else if (option == "dict") {
    std::cout << dict_->words_.size() << std::endl;
    for (int i = 0; i < dict_->words_.size(); i++) {
      std::cout << dict_->getWord(i) << " " << dict_->words_[i].count << " " << (dict_->getType(i) == entry_type::word ? "word" : "label") << std::endl;
    }
  }
}
