    float q_norm = 0.0;
    for (auto x : query_vec) q_norm += x * x;
    q_norm = std::sqrt(q_norm);
    if (q_norm > 0) for (auto& x : query_vec) x /= q_norm;

    std::vector<std::pair<float, std::string>> results;
    for (int i = 0; i < dict_->nwords(); i++) {
